    uid: "sxsw-2026-0496-imax-at-sxsw-stormbound-screening-and-qa@sxfreesw",
    summary: "IMAX at SXSW: STORMBOUND Screening and Q&A",
    description: "Step inside the eye of the storm. An IMAX Original Documentary, \"Stormbound\" thrusts audiences into the heart of the world’s most powerful hurricanes with breathtaking, never-before-seen footage captured from within. As wind, water, and land collide, the film follows storm chaser Jeff Gammons, who for more than thirty years has pushed closer than anyone else to document every major hurricane to strike the United States. Now tested by a near fatal disease , Gammons continues his pursuit—revealing the personal cost of chasing nature at its most extreme and the larger environmental forces shaping our world. \"Stormbound\" is a high-stakes, immersive experience that places audiences face-to-face with nature at its most powerful.",
    dtstart: "20260315T180000",
